reset_tree; run --preflight tRun --keepalive-id k1 >/dev/null
sed -i 's/^phase: .*/phase: LANDING/' memory/builds/tRun/RUN.md
fixture; rm -f "$STOP7"; STOP_UTC=$(date -u +%Y-%m-%dT%H:%M:%SZ)
