ipreset
iprun --preflight tRun --keepalive-id k1 >/dev/null
ipgit add -A >/dev/null && ipgit commit -q -m fixture --no-verify
ip_vb=$(sed -n 's/^base: //p' "$ip_dir/memory/builds/tRun/RUN.md")
