#!/usr/bin/env bash
m=""
for a in "$@"; do case "$a" in --prepare|--land|--carry|--prepared) m=${a#--} ;; esac; done
printf '%s\n' "$m" >> "$DLOUT/lander.log"
if [ "$m" = land ]; then
