run_ln "$LN_NB" --close tLn >/dev/null
same "TOOL-dUnstuckLanding-27 L6 an UNMET bar's record carries no staged set" "$([ -f "$(resolve_ln_staged)" ] && echo present || echo absent)" "absent"
