build_ln_fixture "$LN_VALUE" -
run_ln_preflight "$LN_NB"; write_ln_dod_records "$LN_NB"
run_ln "$LN_NB" --close tLn >/dev/null
printf '\nedited after the bar\n' >> "$ln_root/repo/memory/builds/tLn/spec/one.md"
